 <header class="exam-top"><div class="exam-brand"><img src="/cbt/assets/images/logo.png" alt="Liberty logo"><span><b>LIBERTY CLASS AND CAREER (CBT)</b><small>LIVE MOCK TEST</small></span></div><div class="exam-context-title"><b><?=e($attempt['title'])?></b><span><?=count($questions)?> questions · <?=e($attempt['full_marks'])?> marks</span></div><div class="timer-box"><i>⏱</i><span><small>TIME REMAINING</small><strong data-countdown>--:--:--</strong></span></div></header>
 <div class="exam-grid"><main class="question-panel"><?php foreach($questions as $q):$saved=$responses[$q['id']]??null;$selected=array_filter(explode(',',(string)($saved['selected']??'')));?><article class="exam-question" data-question data-position="<?=e($q['position'])?>" data-question-id="<?=e($q['id'])?>" data-type="<?=e($q['type'])?>" <?=((int)$q['position']===(int)$attempt['current_question_position'])?'':'hidden'?>>
  <div class="question-head"><b>QUESTION <?=e($q['position'])?> OF <?=count($questions)?></b><span class="marks-pill">+<?=e($q['correct_mark'])?> / −<?=e($q['negative_mark'])?> marks</span><em class="sync-status" data-sync-status>✓ All changes saved</em></div><h2><span><?=e($q['position'])?>.</span> <?=e($q['question_text'])?></h2><?php if($q['image_path']):?><img class="question-image" src="/cbt/media/<?=e($q['image_path'])?>" alt="Question illustration"><?php endif;?><div class="answer-options"><?php if($q['type']==='typed'):?><label class="typed-option">Typed answer<input type="text" data-typed-answer value="<?=e($saved['typed_answer']??'')?>"></label><?php else:?><?php foreach($q['options'] as $o):?><label><input type="<?=$q['type']==='multiple'?'checkbox':'radio'?>" name="q<?=e($q['id'])?>" value="<?=e($o['id'])?>" <?=in_array((string)$o['id'],$selected,true)?'checked':''?>><b><?=e($o['option_key'])?></b><span><?=e($o['option_text'])?><?php if(!empty($o['image_path'])):?><img class="option-image" src="/cbt/media/<?=e($o['image_path'])?>" alt="Option <?=e($o['option_key'])?> image"><?php endif;?></span><i aria-hidden="true">✓</i></label><?php endforeach;?><?php endif;?></div><input type="checkbox" data-review <?=!empty($saved['is_marked_review'])?'checked':''?> hidden></article><?php endforeach;?><div class="exam-actions"><button class="btn secondary" type="button" data-prev>← Previous</button><button class="review-button" type="button" data-review-toggle aria-pressed="false"><span aria-hidden="true">◇</span> Mark for review</button><button class="btn" type="button" data-save-next>Save &amp; next →</button></div></main>
 <aside class="question-palette"><div class="palette-heading"><div><h3>Questions</h3><p><b data-question-progress><?=e($answeredInitial)?></b> / <?=count($questions)?></p></div></div><div class="palette-grid"><?php foreach($questions as $q):$s=$responses[$q['id']]??null;$has=$s&&(($s['typed_answer']??'')!==''||($s['selected']??'')!=='');?><button data-go="<?=e($q['position'])?>" class="<?=$has?'answered':''?> <?=!empty($s['is_marked_review'])?'reviewed':''?>"><?=e($q['position'])?></button><?php endforeach;?></div><div class="legend"><span><i class="answered"></i>Saved</span><span><i class="reviewed"></i>Review</span><span><i class="unanswered"></i>Not attempted</span><span><i class="not-visited"></i>Not visited</span></div><button class="btn danger wide" data-final-submit>Final submit</button></aside></div>
